-- name: configuration_changeschedule_update_schedules_enabled_version_updated_at :one
UPDATE control_plane.schedules s SET enabled=$4,next_run_at=CASE WHEN $4 THEN $5 ELSE s.next_run_at END,version=s.version+1,updated_at=clock_timestamp() FROM control_plane.projects p WHERE s.project_id=p.id AND s.organization_id=$1::uuid AND s.ref=$2 AND s.version=$3 AND s.lifecycle_state='ACTIVE' RETURNING s.project_id::text,p.ref,s.ref,s.name,s.preset,s.cron_expression,s.timezone,s.session_policy,s.notification_policy,s.lifecycle_state,s.enabled,s.version,s.next_run_at,s.last_run_at,s.created_at,s.updated_at
